// vector normal to sphere with cener c and radius r
vec3 calcNormal(vec3 p) {
  vec2 e = vec2(0.0015, -0.0015);
  return normalize(
    e.xyy * scene(p + e.xyy).d +
    e.yyx * scene(p + e.yyx).d +
    e.yxy * scene(p + e.yxy).d +
    e.xxx * scene(p + e.xxx).d);
}


struct RaymarchRes {
    Surface s;
    vec3 p; // surface hit point
    float d; // distance
};



RaymarchRes raymarch(vec3 ro, vec3 rd, float maxDist) {
    float t = MIN_DISTANCE; 
    RaymarchRes res;
    res.d = MAX_DISTANCE;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t * rd;
        Surface sf = scene(p); 
        t += sf.d;

        if (sf.d < MIN_DISTANCE) { // we hit the surface at point p
            res.p = p;
            res.s = sf;
            break;
        } else if (sf.d > maxDist) break; // we did not hit anything but are to far away from camera 
    }

    res.d = t;

    return res;
}


mat3 camera(vec3 cameraPos, vec3 lookAtPoint) {
    vec3 cd = normalize(lookAtPoint - cameraPos);
    vec3 cr = normalize(cross(vec3(0, 1, 0), cd));
    vec3 cu = normalize(cross(cd, cr));

    return mat3(-cr, cu, -cd);
}

vec3 calculateCameraPosition(vec3 lookAt, vec2 uv) {
    vec3 ro = vec3(-1., 3.5, -8);
    float cameraTime = iTime * 1.6;
    ro = vec3(cos(cameraTime) * 1.4 - 4.2, 2. + sin(cameraTime) * 3.2 + 2.1, lookAt.z -8. - sin(cameraTime));

    //ro = vec3(-3.6 + REPEAT_SCALE*0.6*cos(iTime*0.5 + iMouse.x*MOUSE_SCALE), REPEAT_SCALE*0.6*sin(iTime*0.5 + iMouse.x*MOUSE_SCALE), 1. -iTime * 8.);

    return ro;
}

vec3 calculateLightPosition(vec3 lookAt) {
    vec3 lightVector = vec3(9., -10, lookAt.z - 1.);
    return lightVector;
}

float calcShadow(in vec3 ro, vec3 rd, float softness){ 
    //float t = MIN_DISTANCE; 
    float res = 1.0;
    float t = 0.;

    ro += rd * MIN_DISTANCE * 2.;

    for (int i = 0; i < MAX_STEPS_SHADOW; i++) {
        vec3 p = ro + t * rd;
        Surface sf = scene(p); 

        if (abs(sf.d) < MIN_DISTANCE) { // we hit the surface at point p so we have not reached light source
            return 0.;
        } else if (sf.d > MAX_SHADOW_DISTANCE) break; // we did not hit anything but are to far away from camera 

        t += sf.d;

        res = clamp(min(res, softness * sf.d / t), 0., 1.);
    }

    return res;
}

vec3 calculateColor(vec3 normalToSurfaceVector, RaymarchRes rr, vec3 rd, vec3 lo, bool shadow) {
    //vec3 normalToSurfaceVector = calcNormal(rr.p);
    vec3 l = normalize(-lo + rr.p); // light direction

    vec3 diffusion = clamp(dot(l, normalToSurfaceVector), 0., 1.) * rr.s.m.diffuseColor;
    float dotRV = clamp(dot(reflect(l, normalToSurfaceVector), rd), 0., 1.);
    vec3 specular =  clamp(1. * pow(dotRV, rr.s.m.alpha), 0., 1.) * rr.s.m.specularColor;

    //float spec =  9.99 * pow(max(dot(view, ret), 0.), 24.);

    float shadowMask = 1.;

    if (shadow) {
        vec3 newRayOrigin = rr.p + normalToSurfaceVector * PRECISION; 
        shadowMask = calcShadow(newRayOrigin, normalize(rr.p - lo), 9.3);
    }
    vec3 color = rr.s.m.ambientColor + (specular + diffusion) * shadowMask;

    return clamp(color, 0., 1.);
}


vec3 calculateReflectedColor(vec3 normalToSurfaceVector, RaymarchRes rr, vec3 rd, vec3 lo) {
    //vec3 normalToSurfaceVector = calcNormal(rr.p);
    vec3 l = normalize(-lo + rr.p); // light direction

    vec3 diffusion = clamp(dot(l, normalToSurfaceVector), 0., 1.) * rr.s.m.diffuseColor;
    float dotRV = clamp(dot(reflect(l, normalToSurfaceVector), rd), 0., 1.);
    vec3 specular =  clamp(1. * pow(dotRV, rr.s.m.alpha), 0., 1.) * rr.s.m.specularColor;

    vec3 color = rr.s.m.ambientColor + (specular + diffusion);
    //reflected color - apply distance correction
    color = mix(color, vec3(0.), 1.0 - exp(-0.000008*rr.d*rr.d*rr.d)); // fog to background

    //cubmap light
    color = 0.5 * color + 0.5  * texture(iChannel0, reflect(rr.p, normalToSurfaceVector)).rgb;


    return clamp(color, 0., 1.);
}

vec3 calculateLight(vec2 fragCoord, RaymarchRes rr, vec3 rd, vec3 lo, vec3 backgroundColor) {
    vec3 normalToSurfaceVector = calcNormal(rr.p);
    // 'base' color (including shadow but no reflection)
    vec3 color = calculateColor(normalToSurfaceVector, rr, rd, lo, false);

    // calculate reflection
    vec3 newRayOrigin = rr.p + normalToSurfaceVector * PRECISION;
    RaymarchRes rrRef = raymarch(newRayOrigin, normalToSurfaceVector, MAX_DISTANCE_REFLECTION);
    // 'reflection' color (including shadow but no reflection
   // if (abs(rr.d) >= 0.) {
        vec3 colorRef = calculateReflectedColor(normalToSurfaceVector, rrRef, rd, lo);
        color = mix(color, colorRef * 0.9, smoothstep(.5,.1, rr.d / 95.));
        //color = color * 1. + colorRef * 0.3;
        //color = colorRef; // 
        color = clamp(color, 0., 1.);
  //  }

    //cubmap light
    color += 0.3  * texture(iChannel0, reflect(rd, normalToSurfaceVector)).rgb;
    vec2 q = fragCoord.xy / iResolution.xy;
    color = vec3(color * pow(20. * q.x * q.y * (1.0 - q.x) * (1.0 - q.y), 0.8)); // vigniete
    color = mix(color, backgroundColor, 1.0 - exp(-0.000003*rr.d*rr.d*rr.d)); // fog to background


/*
    // gamma correction basic

    float gammaCorr = 0.45;
    color = pow(color, vec3(0.45));
  */  
    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
    float sTime = mod(iTime, TIME_LOOP) * 8.;
    vec3 lookAt = vec3(sin(sTime / 24.) * 3., sin(sTime / 24.) * 9., sTime);
    vec3 ro = calculateCameraPosition(lookAt, uv);

    vec3 rd = camera(ro, lookAt) * normalize(vec3(uv, -1.));
    vec3 lo = calculateLightPosition(lookAt);
    vec4 backgroundColor = vec4(mix(vec3(0., 0.1, .2), vec3(0., 0., 0.), uv.y) * 1.1, 1.0);
    RaymarchRes rr = raymarch(vec3(ro.x, ro.y, ro.z), rd, MAX_DISTANCE);
    //rd *= 4.;
    backgroundColor = texture(iChannel0, vec3(rd.x, rd.y + 0.9, rd.z + 0.1));
    fragColor = (rr.d < MAX_DISTANCE) ? vec4(calculateLight(fragCoord, rr, rd, lo, backgroundColor.xyz), 1.0) : backgroundColor;    
    //fragColor = blink(fragColor, vec4(1.,1., 1., 0.));
}
